"""Build Golden Alchemy's static pages. No dependencies or secrets required."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1] / 'docs'
NAV = [('home', 'Home'), ('forum', 'Forum'), ('theoracle', 'The Oracle'), ('marketplace', 'Marketplace'), ('about', 'About')]
IG = 'https://www.instagram.com/goldenalchemy.na/'
TT = 'https://www.tiktok.com/@goldenalchemy.net'
PHOTOS = {
    'hero': 'photo-1555939594-58d7cb561ad1',
    'guild': 'photo-1556911220-bff31c812dba',
    'oracle': 'photo-1512621776951-a57141f2eefd',
    'bazaar': 'photo-1596040033229-a9821ebd058d',
}

def image(key, alt, eager=False):
    url = f'https://images.unsplash.com/{PHOTOS[key]}'
    return f'<img src="{url}?auto=format&amp;fit=crop&amp;w=1400&amp;q=85" srcset="{url}?auto=format&amp;fit=crop&amp;w=600&amp;q=80 600w, {url}?auto=format&amp;fit=crop&amp;w=1400&amp;q=85 1400w" sizes="(max-width: 700px) 100vw, 65vw" alt="{escape(alt)}" {"fetchpriority=\"high\"" if eager else "loading=\"lazy\""} width="1400" height="1000">'

def eyebrow(text):
    return f'<p class="eyebrow">{text}</p>'

def intro(kicker, title, text):
    return f'<section class="page-intro wrap">{eyebrow(kicker)}<h1>{title}</h1><p class="lead">{text}</p></section>'

def notice(title, text, symbol='✧'):
    return f'<div class="empty-state"><span class="empty-symbol" aria-hidden="true">{symbol}</span><h3>{title}</h3><p>{text}</p></div>'

def header(active):
    links = ''.join(f'<a href="/{slug}/" {"aria-current=\"page\"" if slug == active else ""}>{title}</a>' for slug, title in NAV)
    return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="nav-wrap"><a class="brand" href="/home/" aria-label="Golden Alchemy home"><span class="brand-seal" aria-hidden="true">△<i>✧</i></span><span>GOLDEN ALCHEMY<small>THE ART OF TRANSFORMATION</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu <span aria-hidden="true">☰</span></button><nav id="main-nav" aria-label="Main navigation">{links}<button class="signin" data-community>Sign in <span aria-hidden="true">↗</span></button></nav></div></header>'''

def footer():
    links = ''.join(f'<a href="/{slug}/">{title}</a>' for slug, title in NAV)
    return f'''<footer class="site-footer"><div class="wrap footer-top"><div><a class="footer-brand" href="/home/">GOLDEN ALCHEMY<span aria-hidden="true">✧</span></a><p>The art of transformation.</p></div><nav aria-label="Footer navigation">{links}</nav><div class="footer-social"><span class="eyebrow">COME INTO THE KITCHEN</span><a href="{IG}" target="_blank" rel="noopener noreferrer">Instagram ↗</a><a href="{TT}" target="_blank" rel="noopener noreferrer">TikTok ↗</a></div></div><div class="wrap footer-bottom"><span>© <span data-year>2026</span> Golden Alchemy · Chef Rain</span><button class="text-button" data-policy>Privacy &amp; site information</button></div></footer>'''

def home():
    from home_page import render_home
    return render_home(image, eyebrow, IG, TT)

def forum():
    return intro('THE COMMUNITY / COMING TO THE TABLE', 'Chef Rain’s Guild.', 'Every kind of chef. Every kind of kitchen. A future gathering place to share your work and learn from one another.') + f'''<section class="wrap guild-layout"><div class="guild-main"><div class="toolbar"><h2>The shared table</h2><span class="status">COMMUNITY COMING SOON</span></div><div class="guild-photo">{image('guild', 'Food preparation in a shared kitchen')}<span class="image-caption">A space for the craft. A place for the people.</span></div>{notice('The table is being set.', 'Dish uploads, likes, comments, and profiles will open when community accounts are ready. No posts or reactions are being collected yet.')}<div class="community-features"><div><span>01</span><h3>Share your craft</h3><p>Photos, films, and the stories behind a finished dish.</p></div><div><span>02</span><h3>Find your people</h3><p>Profiles with your specialty, biography, gallery, and social links.</p></div></div></div><aside class="guild-sidebar"><div class="panel copper-panel">{eyebrow('YOUR PLACE IN THE GUILD')}<h2>Chef comes first.</h2><p>Every public handle will begin with <strong>chef</strong>. From home cooks to seasoned professionals, everyone has a place.</p><div class="handle-example">@chefRain <span>EXAMPLE HANDLE</span></div><button class="button" data-community>Account availability →</button></div><div class="panel"><span class="status">PLANNED FEATURE</span><h3>Kitchen conversation</h3><p>Global chat for signed-in members. Chat and messaging are not active yet.</p></div><p class="small muted">Accounts, storage, moderation, reporting, and blocking will be configured before the community opens.</p></aside></section>'''

def oracle():
    recipe = f'''<article class="panel recipe-panel"><div class="panel-top">{eyebrow('01 / RECIPE DISCOVERY')}<span class="status">COMING SOON</span></div><h2>What’s in your kitchen?</h2><p>Discover dishes by name or ingredient.</p><form id="recipe-preview"><label for="recipe-query">Recipe or ingredient</label><div class="search-row"><input id="recipe-query" name="query" placeholder="Try roasted tomatoes…" maxlength="100" required><button class="button" type="submit">Search <span aria-hidden="true">→</span></button></div><p id="recipe-message" class="small" aria-live="polite">Recipe search will connect to TheMealDB in a later update.</p></form><div class="oracle-photo">{image('oracle', 'Fresh vegetables and grains in a bowl')}</div></article>'''
    recalls = f'''<article class="panel recall-panel" id="food-recalls"><div class="panel-top">{eyebrow('02 / FOOD RECALLS')}<span class="status" id="recall-state" role="status">LOADING</span></div><h2>Know what’s on your table.</h2><p>Six recent FDA food-enforcement records, ordered by report date. Expand a record for product, reason, distribution, and lot information.</p><p class="recall-context">This is a limited enforcement-report preview, not a real-time alert service or a complete list of recalls. Report dates may lag announcements; check the official FDA notices for current instructions.</p><p class="source-note" id="recall-dates"></p><div id="recall-results" aria-live="polite"><div class="skeleton" aria-label="Loading FDA records"></div></div><noscript><p>Enable JavaScript to view the preview, or use the official FDA links below.</p></noscript><a class="underlink" href="https://www.fda.gov/safety/recalls-market-withdrawals-safety-alerts" target="_blank" rel="noopener noreferrer">Check official FDA notices ↗</a><a class="recall-source" href="https://open.fda.gov/apis/food/enforcement/" target="_blank" rel="noopener noreferrer">Source: openFDA food enforcement reports ↗</a></article>'''
    weather = f'''<article class="panel weather-panel" id="city-weather"><div class="panel-top">{eyebrow('03 / OUTSIDE THE KITCHEN')}<span class="status" id="weather-state" role="status">LOADING</span></div><h2>A taste of the season.</h2><p>A forecast for your next kitchen day. Choose a New York city—no location tracking.</p><div class="weather-controls"><div><label for="weather-city">Forecast city</label><select id="weather-city"><option value="new-york">New York City</option><option value="albany">Albany, NY</option><option value="buffalo">Buffalo, NY</option></select></div><div class="filters" role="group" aria-label="Temperature units"><button type="button" class="filter active" data-weather-unit="F" aria-pressed="true">°F</button><button type="button" class="filter" data-weather-unit="C" aria-pressed="false">°C</button></div></div><div id="weather-results" aria-live="polite"><div class="skeleton" aria-label="Loading city forecast"></div></div><p class="source-note" id="weather-dates"></p><a class="underlink" id="weather-source" href="https://www.weather.gov/" target="_blank" rel="noopener noreferrer">Source: National Weather Service ↗</a><p class="small weather-note">Forecast temperatures and conditions, not live observations. Updated with the site’s scheduled refresh.</p><noscript><p>Enable JavaScript for the forecast preview or use the NWS source link.</p></noscript></article>'''
    journal = f'''<article class="panel editorial-panel">{eyebrow('04 / THE KITCHEN JOURNAL')}<h2>Notes worth keeping.</h2><p>Ingredient discoveries, cooking techniques, and stories from the kitchen will find a home here.</p><div class="journal-line"><span>IN SEASON</span><span>Coming soon</span></div><div class="journal-line"><span>AT THE WORKBENCH</span><span>Coming soon</span></div><div class="journal-line"><span>FROM CHEF RAIN</span><span>Coming soon</span></div></article>'''
    return intro('DISCOVER / LEARN / EXPERIMENT', 'Global News Feed.', 'Good cooking begins with curiosity. Explore official food-enforcement reports and New York weather forecasts, with recipe discovery still to come.') + f'<section class="wrap oracle-grid">{recipe}{recalls}{weather}{journal}</section>'

def marketplace():
    services = [('01', 'Meal preparation', 'Thoughtful meals for the everyday table.', 'New York', 'Inquire on Instagram'), ('02', 'Catering', 'Gather around food made for the occasion.', 'New York', 'Inquire on Instagram'), ('03', 'Online cooking classes', 'Learn, experiment, and cook alongside the community.', 'Future members-only offering', 'Ask about future classes')]
    products = [('Hardcover cookbooks', 'Kitchen wisdom, made to keep.'), ('Digital cookbooks', 'New inspiration, wherever you cook.'), ('Signature seasonings', 'A little alchemy for your pantry.'), ('Golden Alchemy goods', 'Made for a life around the table.')]
    service_html=''.join(f'<article class="service-card"><span class="service-number">{n}</span><span class="status">PLANNED OFFERING</span><h3>{title}</h3><p>{desc}</p><p class="small">{area}</p><div class="card-bottom"><span>Pricing coming soon</span><a href="{IG}" target="_blank" rel="noopener noreferrer">{cta} ↗</a></div></article>' for n,title,desc,area,cta in services)
    product_html=''.join(f'<article class="product-card"><div class="product-art" aria-hidden="true"><span>{["▤","▱","✧","◇"][i]}</span><small>GOLDEN ALCHEMY</small></div><span class="status">IN DEVELOPMENT</span><h3>{title}</h3><p>{desc}</p><span class="small muted">Pricing coming soon · Not yet available</span></article>' for i,(title,desc) in enumerate(products))
    return intro('SERVICES / GOODS / GOOD TASTE', 'Chef Rain’s Marketplace.', 'From the New York table to your own pantry. A collection of services and culinary goods, taking shape with care.')+f'''<section class="wrap market-section"><div class="market-banner">{image('bazaar', 'An assortment of aromatic spices')}<div>{eyebrow('MADE WITH INTENTION')}<h2>Bring a little<br>alchemy home.</h2></div></div><div class="section-heading"><span class="eyebrow">01 / AT YOUR TABLE</span><h2>Services by Chef Rain.</h2><p>Offerings are in development. Inquiries open on Instagram; bookings are not confirmed through this website.</p></div><div class="service-grid">{service_html}</div></section><section class="wrap section"><div class="section-heading">{eyebrow('02 / FROM THE PANTRY')}<h2>The collection to come.</h2><p>A first look at the categories we’re preparing. No products are available for purchase yet.</p></div><div class="product-grid">{product_html}</div></section>'''

def about():
    return intro('THE PERSON BEHIND THE PLATE', 'The Artisan’s Story.', 'Chef Rain · Golden Alchemy')+f'''<section class="wrap about-layout"><div class="about-visual">{image('hero', 'An editorial platter of grilled meats and vegetables')}<span class="image-caption">Inspired by the hearth. Open to discovery.</span></div><div class="about-copy">{eyebrow('WELCOME TO MY KITCHEN')}<h2>Food is an act<br>of transformation.</h2><p class="lead">Golden Alchemy is Chef Rain’s home for cooking, creative exploration, and the knowledge we share around food.</p><p>Traditional techniques and fresh curiosity belong at the same table. Fire, water, earth, and air are a way of seeing the craft—an invitation to pay attention to what happens between ingredient and finished dish.</p><p>This space is growing into a portfolio, a community for chefs of all kinds, and a home for future culinary offerings.</p><a class="underlink" href="https://www.instagram.com/goldenalchemy.na/">See Chef Rain’s work on Instagram →</a><div class="signature">Chef Rain <span>GOLDEN ALCHEMY</span></div></div></section><section class="contact-section wrap section"><div>{eyebrow('LET’S TALK FOOD')}<h2>A conversation<br>starts here.</h2></div><div class="contact-options"><a href="{IG}" target="_blank" rel="noopener noreferrer"><span>Instagram<small>@goldenalchemy.na · Send a direct message</small></span><span aria-hidden="true">↗</span></a><div><span>Email<small>Coming soon</small></span><span class="status">IN THE WORKS</span></div></div></section>'''

PAGES = {'home':(home,'Simple Ingredients. Extraordinary Possibilities.','Chef Rain’s culinary world. Discover the philosophy, latest creations, and future community of Golden Alchemy.'),'forum':(forum,"Chef Rain’s Guild",'A future culinary community for chefs of all kinds. Explore the Golden Alchemy guild.'),'theoracle':(oracle,'Global News Feed','Recipe discovery, seasonal inspiration, and food information. Explore the future Culinary Oracle.'),'marketplace':(marketplace,'Chef Rain’s Marketplace','Explore planned culinary services in New York, cookbooks, and signature seasonings by Golden Alchemy.'),'about':(about,"The Artisan’s Story",'Meet the idea behind Golden Alchemy and connect with Chef Rain on Instagram.')}

def build():
    for element in ('fire', 'water', 'earth', 'air'):
        # Keep the article area empty until the owner starts the editorial phase.
        PAGES[element] = (lambda: '<section class="element-placeholder wrap" style="min-height:35vh" aria-label="Future element articles"></section>', element.title(), 'Golden Alchemy culinary elements.')
    for slug,(render,title,description) in PAGES.items():
        folder=ROOT/slug
        folder.mkdir(parents=True,exist_ok=True)
        document=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#2A1A0E"><title>{escape(title)} | Golden Alchemy</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="https://www.goldenalchemy.net/{slug}/"><meta property="og:title" content="{escape(title)} | Golden Alchemy"><meta property="og:description" content="{escape(description)}"><meta property="og:type" content="website"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=Outfit:wght@300;400;500;600;700&amp;display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body>{header(slug)}<main id="main">{render()}</main>{footer()}<dialog id="info-dialog" aria-labelledby="dialog-title"><button class="dialog-close" aria-label="Close dialog">×</button><p class="eyebrow">GOLDEN ALCHEMY</p><h2 id="dialog-title"></h2><div id="dialog-content"></div></dialog><dialog id="media-dialog" aria-label="Gallery media"><button class="dialog-close" aria-label="Close media">×</button><div id="media-content"></div></dialog></body></html>'''
        document = document.replace('<script src="/assets/site.js"', '<link rel="stylesheet" href="/assets/integrations.css"><script src="/assets/site.js"')
        document = document.replace('>TikTok ↗</a>', '>TikTok — Extended videos ↗</a>')
        if slug == 'home':
            document = document.replace('</head>', '<link rel="stylesheet" href="/assets/home.css"></head>')
        if slug in ('fire', 'water', 'earth', 'air'):
            document = document.replace('</head>', '<meta name="robots" content="noindex"></head>')
        if slug == 'theoracle':
            document = document.replace('</head>', '<script src="/assets/oracle.js" defer></script><script src="/assets/weather.js" defer></script></head>')
        (folder/'index.html').write_text(document,encoding='utf-8')
    (ROOT/'index.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url=/home/"><link rel="canonical" href="https://www.goldenalchemy.net/home/"><title>Golden Alchemy</title><script>location.replace('/home/'+location.search+location.hash)</script></head><body><a href="/home/">Enter Golden Alchemy</a></body></html>''',encoding='utf-8')
    (ROOT/'404.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found | Golden Alchemy</title><link rel="stylesheet" href="/assets/site.css"></head><body><main class="wrap section"><p class="eyebrow">GOLDEN ALCHEMY / 404</p><h1>A little off the menu.</h1><p>We couldn’t find that page.</p><a class="button" href="/home/">Return to the kitchen →</a></main></body></html>''',encoding='utf-8')
    print(f'Built {len(PAGES)} Golden Alchemy pages and root redirect.')

if __name__=='__main__':
    build()
